#include <stdio.h>
#include <string.h>

/* check if byte b is one of: space, \t, \n, \v, \f, \r */
static int is_ws(unsigned char b) {
    return b == ' ' || b == '\t' || b == '\n' || b == '\v' || b == '\f' || b == '\r';
}

int main(void) {
    int lines = 0;
    int words = 0;
    long num_bytes = 0;
    int maxlen = 0;
    int curline_len = 0;
    int in_word = 0;

    unsigned char buf[4096];

    while ((size_t)fread(buf, 1, sizeof buf, stdin) > 0) {
        size_t i;
        for (i = 0; i < sizeof buf; i++) {
            unsigned char b = buf[i];
            num_bytes++;
            curline_len++;

            if (b == '\n') {
                lines++;
                if (curline_len > maxlen)
                    maxlen = curline_len;
                curline_len = 0;
            }

            if (is_ws(b)) {
                if (in_word) {
                    words++;
                    in_word = 0;
                }
            } else {
                in_word = 1;
            }
        }
    }

    /* handle last line: if there's data beyond the last \n, it's still a line */
    if (curline_len > maxlen)
        maxlen = curline_len;
    if (!in_word) {
        /* no trailing word to count past \n or EOF in whitespace */
        if (num_bytes == 0) {
            /* empty input */
            printf("0 0 0 0\n");
        }
    } else {
        words++;
    }

    /* For completely empty input: lines=0, words=0, bytes=0 */
    if (num_bytes == 0) {
        printf("0 0 0 %d\n", maxlen);
        return 0;
    }

    printf("%d %ld %ld %d\n", lines, words, num_bytes, maxlen);
    return 0;
}

